create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text not null, email text, role text not null default 'user' check(role in ('user','admin')), vehicle_number text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.parking_slots (id uuid primary key default gen_random_uuid(), slot_number text unique not null check(slot_number ~ '^[A-Z][0-9]{2}$'), floor integer not null default 1 check(floor > 0), section text, status text not null default 'available' check(status in ('available','reserved','occupied','maintenance')), vehicle_number text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reservations (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, slot_id uuid not null references public.parking_slots(id) on delete cascade, vehicle_number text not null, start_time timestamptz not null, end_time timestamptz not null, status text not null default 'active' check(status in ('active','completed','cancelled','expired')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(end_time > start_time));
create index reservations_user_id_idx on public.reservations(user_id); create index reservations_slot_id_idx on public.reservations(slot_id); create index reservations_status_idx on public.reservations(status); create index reservations_start_time_idx on public.reservations(start_time); create index reservations_end_time_idx on public.reservations(end_time); create index parking_slots_status_idx on public.parking_slots(status); create index parking_slots_number_idx on public.parking_slots(slot_number);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger slots_updated before update on public.parking_slots for each row execute function public.set_updated_at(); create trigger reservations_updated before update on public.reservations for each row execute function public.set_updated_at();
create or replace function public.create_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,name,email) values(new.id,coalesce(new.raw_user_meta_data->>'name',split_part(new.email,'@',1)),new.email); return new; end $$;
create trigger auth_profile after insert on auth.users for each row execute function public.create_profile();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security; alter table public.parking_slots enable row level security; alter table public.reservations enable row level security;
create policy profiles_read_own on public.profiles for select using(id=auth.uid() or public.is_admin()); create policy profiles_update_own on public.profiles for update using(id=auth.uid()) with check(id=auth.uid() and role=(select role from public.profiles where id=auth.uid()));
create policy slots_read on public.parking_slots for select to authenticated using(true); create policy slots_admin_write on public.parking_slots for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy reservations_read on public.reservations for select using(user_id=auth.uid() or public.is_admin()); create policy reservations_admin_update on public.reservations for update using(public.is_admin()) with check(public.is_admin());
create or replace function public.reserve_parking_slot(p_slot_id uuid,p_vehicle_number text,p_start_time timestamptz,p_end_time timestamptz) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; v_status text; begin if auth.uid() is null then raise exception 'Not authenticated'; end if p_start_time<=now() or p_end_time<=p_start_time or p_end_time-p_start_time>interval '24 hours' then raise exception 'Invalid reservation time'; end if; select status into v_status from parking_slots where id=p_slot_id for update; if not found or v_status<>'available' then raise exception 'Slot unavailable'; end if; if exists(select 1 from reservations where slot_id=p_slot_id and status='active' and tstzrange(start_time,end_time,'[)') && tstzrange(p_start_time,p_end_time,'[)')) then raise exception 'Slot unavailable'; end if; insert into reservations(user_id,slot_id,vehicle_number,start_time,end_time) values(auth.uid(),p_slot_id,upper(p_vehicle_number),p_start_time,p_end_time) returning id into v_id; update parking_slots set status='reserved',vehicle_number=upper(p_vehicle_number) where id=p_slot_id; return v_id; end $$;
create or replace function public.cancel_reservation(p_reservation_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_slot uuid; begin select slot_id into v_slot from reservations where id=p_reservation_id and user_id=auth.uid() and status='active' for update; if not found then raise exception 'Active reservation not found'; end if; update reservations set status='cancelled' where id=p_reservation_id; if not exists(select 1 from reservations where slot_id=v_slot and status='active' and end_time>now()) then update parking_slots set status='available',vehicle_number=null where id=v_slot and status='reserved'; end if; end $$;
create or replace function public.expire_reservations() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin with expired as (update reservations set status='expired' where status='active' and end_time<=now() returning slot_id) update parking_slots s set status='available',vehicle_number=null where s.id in(select distinct slot_id from expired) and not exists(select 1 from reservations r where r.slot_id=s.id and r.status='active' and r.end_time>now()); get diagnostics n=row_count; return n; end $$;
grant execute on function public.reserve_parking_slot(uuid,text,timestamptz,timestamptz) to authenticated; grant execute on function public.cancel_reservation(uuid) to authenticated; grant execute on function public.expire_reservations() to service_role;
alter publication supabase_realtime add table public.parking_slots, public.reservations;
create extension if not exists pg_cron;
do $$ begin if not exists (select 1 from cron.job where jobname='expire-parking-reservations') then perform cron.schedule('expire-parking-reservations','*/5 * * * *','select public.expire_reservations()'); end if; end $$;
